from pathlib import Path
import subprocess,html
root=Path(__file__).resolve().parents[1]; out=root/'relatorio-p2'
base='https://github.com/luisciaramicoli/postcraft-ai'
def link(path,label):return f'<a href="{base}/{path}">{label}</a>'
def page(title,body,id=''):return f'<section id="{id}"><h1>{title}</h1>{body}</section>'
def p(t):return '<p>'+t+'</p>'
def img(path,caption):return f'<figure><img src="{path}"><figcaption>{caption}</figcaption></figure>'
parts=[]
parts.append(page('P2 — Relatório consolidado', '<div class="cover"><p>Fatec Pompeia · ISW055</p><h2>Introdução à Computação em Nuvem</h2><h2>PostCraft AI</h2><p>Luis Gustavo Bonfim Ciaramicoli</p><p>Turma: 161_SIST. INTELIGENTES_N</p><p>Professor: Allan Lincoln Rodrigues Siriani</p><p>12 de novembro de 2026</p>'+link('','Repositório do produto')+p('Relatório individual de arquitetura e atividades 7 a 11. Levantamento documental com limitações explicitadas; não constitui comprovação de implantação pública.')+'</div>'))
titles=['Introdução','Metodologia','Arquitetura do SaaS','Quadro de entregas','Atividades realizadas','Considerações finais','Declaração de autoria']
parts.append(page('Sumário','<ol>'+''.join(f'<li><a href="#s{i}">{t}</a></li>' for i,t in enumerate(titles,1))+'</ol>'+p('Os links internos levam às seções correspondentes. As fichas individuais contêm links diretos para as evidências. Horários das entregas em America/Sao_Paulo (UTC−03:00).')))
parts.append(page('1 Introdução',p('O PostCraft AI é a evolução do catálogo CineCloud desenvolvido na disciplina Introdução à Computação em Nuvem. A base de autenticação, auditoria, armazenamento de arquivos e pagamento foi reaproveitada para um domínio de publicações e marcas. O público proposto são profissionais autônomos que precisam produzir conteúdo recorrente para o Instagram, mas dispõem de pouco tempo para organizar roteiros, legendas e identidade visual.')+p('O produto propõe um plano gratuito e uma assinatura Creator Pro. A mudança de domínio exige mais que trocar telas: as permissões, o vínculo entre usuário e dados, a cobrança recorrente e os limites precisam ser verificáveis no servidor. Este relatório apresenta a arquitetura encontrada no repositório do produto, as evidências das atividades do bimestre e as lacunas que impedem afirmar que o SaaS está completo.')+p('O recorte principal é o commit d084645, último commit do produto consultado. Há evolução posterior no repositório da base, incluindo Gemini e correções de interface, mas ela não é atribuída automaticamente ao produto publicado.'),'s1'))
parts.append(page('2 Metodologia',p('Foram consultados o enunciado da P2, o histórico Git, as issues de entrega, os arquivos Docker Compose, as rotas e controladores de backend, o esquema SQL e o pipeline de integração contínua. Uma cópia isolada do repositório do produto foi usada para produzir este documento, preservando alterações locais não commitadas em outro diretório.')+p('As datas de implementação das atividades 7 e 8 vêm dos commits. Para 9 e 10, foram utilizadas as datas de abertura das issues de entrega, convertidas de UTC para UTC−03:00. O histórico anterior foi preservado na cópia do repositório, permitindo localizar os mesmos commits da base. Data de código ou issue não comprova, isoladamente, aprovação pelo professor nem funcionamento de todas as funções anunciadas.')+p('As capturas de commits e issues são de páginas reais do GitHub; os registros textuais adjacentes preservam as datas exatas extraídas do Git. Imagens de checkout e assinatura já presentes na documentação são evidências históricas, não novos testes. Os testes locais de 12/11/2026 pertencem à versão mais recente da base e foram usados somente como diagnóstico complementar. A URL pública do produto foi confirmada em 13/11/2026: https://luis-ciaramicoli-isw055.lapps.studio/. A stack Portainer aponta para o commit 32b09ef e os containers estão saudáveis.')+p('A redação e a montagem do documento tiveram assistência de IA. Não foram criados registros fictícios de pagamento, aprovação, publicação ou entrega. A atividade 11 permanece identificada como não entregue neste levantamento.'),'s2'))
arch=p('3.1 Componentes e microsserviços')+'''<div class="diagram">Navegador → domínio / proxy (publicação não verificada) → app:3000<br>app → auth-service → MariaDB externo<br>app → MariaDB · app → MinIO · app → Stripe Checkout<br>Stripe → webhook no app → MariaDB<br>app / auth → log-service → Redis Streams<br>Prometheus → métricas dos serviços → Grafana</div>'''+p('O app reúne frontend compilado e API Express. O auth-service centraliza login, sessão e autorização. O log-service recebe eventos estruturados e os grava no Redis. O MariaDB mantém usuários e domínio; MinIO guarda objetos binários. Stripe é o serviço externo de cobrança. O Compose expõe a porta 8218 do app; auth, log e MinIO se comunicam por nomes de serviço na rede Docker. O banco é indicado por DB_HOST, não é definido como serviço nesses arquivos.')+ '<h2>3.2 Onde roda</h2>'+p('O Compose de produção referencia imagens GHCR postcraft-app, postcraft-auth e postcraft-log-service. A issue 8 declara uso de Portainer, mas informa apenas http://localhost:8218. Não há evidência suficiente de domínio público, identidade da VM ou nome da stack; esses dados precisam ser confirmados pelo autor. A stack observada localmente se chama cloud-atividade e executa uma versão posterior da base, não necessariamente a imagem do produto.')+p('Os arquivos não definem limites de memória por container. Redis tem maxmemory de 256 MB, que limita sua memória de dados, não toda a stack. Portanto, a declaração de 1 GB feita na issue não foi tratada como configuração comprovada.')+p('Variáveis relevantes, somente nomes: DB_HOST, DB_USER, DB_PASSWORD, DB_NAME, JWT_SECRET, AUTH_SERVICE_URL, LOG_SERVICE_URL, MINIO_ENDPOINT, MINIO_ACCESS_KEY, MINIO_SECRET_KEY, MINIO_BUCKET, STRIPE_SECRET_KEY, STRIPE_PRICE_ID, STRIPE_WEBHOOK_SECRET, SMTP_USER, SMTP_PASS, PUBLIC_URL, COOKIE_SECURE e CORS_ORIGINS. O Compose de produção contém defaults inseguros que devem ser substituídos; seus valores não são reproduzidos aqui.')
parts.append(page('3 Arquitetura do SaaS',arch,'s3'))
parts.append(page('3 Arquitetura — fluxos', '<h2>3.3 Fluxo de uma requisição</h2>'+p('Na criação de um post, o navegador envia a requisição à API na mesma origem. O middleware verifica a sessão e consulta o serviço de autorização para o papel exigido. O controlador valida os campos e associa o registro ao usuário autenticado. O MariaDB persiste o post e, quando aplicável, a marca. O serviço de logs registra o evento de negócio e a API retorna o resultado. Na listagem, usuários comuns recebem registros filtrados por usuario_id; o administrador tem caminho específico para consulta ampliada.')+p('O endpoint de geração do produto no commit d084645 utiliza generateMockAIContent, uma composição heurística de textos. A integração real com Gemini está na evolução posterior da base. Ela não pode ser apresentada como capacidade já comprovada daquela versão do produto.')+'<h2>3.4 Fluxo de assinatura</h2>'+p('O app cria uma Checkout Session em modo subscription com o preço configurado. A confirmação efetiva depende do webhook, não do retorno do navegador. O controlador valida a assinatura com constructEvent e STRIPE_WEBHOOK_SECRET sobre o corpo bruto. checkout.session.completed associa stripe_customer_id e stripe_subscription_id ao usuário e ativa premium; customer.subscription.deleted remove o benefício.')+p('Não foi localizada rota de portal do cliente nem armazenamento de IDs de eventos para deduplicação. Repetir a atribuição premium=1 pode manter o mesmo valor, mas isso não constitui idempotência completa: eventos e efeitos secundários podem se repetir. Também não foi comprovado bloqueio mensal de três gerações no controlador do produto. A promessa comercial Free × Pro excede o que foi validado no código.')+p('No diagnóstico local posterior, o checkout retornou erro de credencial OAuth expirada. Não houve assinatura de teste concluída neste levantamento. A credencial configurada foi suficiente para validar o fluxo de geração de conteúdo, mas não foi feito pagamento de teste. É necessário renovar a configuração, testar webhook, cancelamento, repetição de eventos e enforcement das cotas antes de considerar a atividade 11 concluída.')))
parts.append(page('3 Arquitetura — dados e segurança','<h2>3.5 Modelo de dados do domínio</h2>'+'''<table><tr><th>Entidade</th><th>Chaves e finalidade</th></tr><tr><td>usuarios</td><td>id; nome, email, senha, role, bio, avatar_key, premium, stripe_customer_id, stripe_subscription_id.</td></tr><tr><td>marcas</td><td>id; usuario_id → usuarios.id (CASCADE); nome, nicho, paleta_cores, logo_url.</td></tr><tr><td>posts</td><td>id; usuario_id → usuarios.id (CASCADE); marca_id → marcas.id (SET NULL); titulo, nicho, formato, slides_json, legenda, hashtags, status, imagem_url.</td></tr><tr><td>templates</td><td>id; titulo, nicho, formato, estrutura_json, prompt_base. Sem vínculo individual de usuário no script.</td></tr><tr><td>reset_tokens</td><td>Tokens de recuperação vinculados ao usuário, com expiração, mantidos pelo auth-service.</td></tr></table>'''+p('A migração db/001_dominio.sql usa explicitamente cloud_atividade e remove favoritos e comentarios. Esse nome deve ser alinhado ao DB_NAME da implantação; o Compose de produção usa outro padrão. A tabela limites_usuario aparece no backlog, mas não foi encontrada na migração do produto.')+'<h2>3.6 Segurança</h2>'+p('Criador e administrador podem executar mutações do domínio; revisor fica restrito à leitura. As rotas aplicam autenticação e autorização no backend. Para atualizar ou excluir um recurso, o controlador compara o proprietário com o identificador da sessão e permite exceção administrativa. Consultas parametrizadas reduzem risco de injeção SQL.')+p('O JWT é transportado em cookie e os serviços usam configuração de ambiente. É necessário revisar os defaults de segredos no Compose de produção, configurar HTTPS e cookie seguro e verificar a propagação dos papéis até a interface. Declarações de isolamento no README não substituem testes com duas contas e tentativas de acesso cruzado.')+'<h2>3.7 Observabilidade e CI/CD</h2>'+p('Há healthchecks, métricas Prometheus, Grafana, Swagger/OpenAPI e pipeline GitHub Actions. O pipeline instala dependências, executa testes dos três serviços e valida build; as imagens publicadas no GHCR são referenciadas pelo Compose de produção. Watchtower está previsto para atualizar imagens. Não foi confirmada uma execução recente de implantação pública neste relatório.')+'<h2>3.8 IaaS, PaaS e SaaS</h2>'+p('IaaS: VM e rede, administradas pelo responsável pelo host. PaaS: camada de execução e entrega formada por Docker/Portainer e automação GitHub Actions/GHCR; são ferramentas operadas pelo projeto, não prova de contratação de PaaS gerenciado. SaaS: Stripe e o próprio PostCraft AI oferecido ao usuário. MinIO é software de armazenamento operado na infraestrutura do projeto.')))
rows=[('7','Plano Premium','09/10/2026','15/10/2026 14:19','Entregue com atraso','35adf09','Implementação de checkout e webhook herdada do CineCloud. As imagens históricas abaixo documentam o contexto original; não comprovam uma assinatura atual do PostCraft.'),
('8','Documentação e camadas','16/10/2026','15/10/2026 14:32','Entregue','62c3eda','DOCUMENTACAO.md e ligação no README registram a documentação reversa. O documento original descreve CineCloud; a seção 3 deste relatório explicita as diferenças do domínio PostCraft.'),
('9','Fork e plano de negócio','23/10/2026','06/11/2026 20:57','Entregue com atraso','98a0946','Issue 7 registra o novo repositório, o histórico preservado, a proposta de valor, persona, receita, Lean Canvas e backlog. A cópia do histórico existe, mas a entrega foi registrada depois do prazo.'),
('10','Seu negócio no ar','06/11/2026','06/11/2026 21:16','Entrega registrada; validação parcial','ad95547','Issue 8 registra implementação do domínio e aponta localhost como URL. Há código de posts, marcas, landing e RBAC; a disponibilidade pública e os prints de 403 e logs específicos do novo domínio não foram comprovados.'),
('11','SaaS completo','13/11/2026','13/11/2026 — parcial','Parcial; não marcar como completa','', 'Após configurar a chave do Gemini na stack, foi validado login e POST /api/posts/generate com HTTP 201, cinco slides, legenda e hashtags. O próprio serviço retornou aviso de cota esgotada para imagem e usou fundo padrão. Portal do cliente, idempotência de webhook, cota mensal comprovada e pagamento de teste ainda não foram validados; por isso a atividade não é declarada completa.')]
parts.append(page('4 Quadro de entregas','<table><tr><th>Nº</th><th>Atividade</th><th>Planejada</th><th>Realizada (UTC−03)</th><th>Situação</th></tr>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r[:5])+'</tr>' for r in rows)+'</table>'+p('Quadro e fichas gerados a partir do mesmo conjunto de registros. “Entrega registrada” identifica a issue, não uma certificação de completude. Não foi calculada nota; a avaliação cabe ao professor.'),'s4'))
for n,name,planned,date,status,commit,desc in rows:
 body=f'<h2>{name}</h2><table><tr><th>Planejada</th><td>{planned}</td></tr><tr><th>Realizada</th><td>{date} (UTC−03:00)</td></tr><tr><th>Situação</th><td>{status}</td></tr></table>'+p(desc)
 if commit:
  sha=subprocess.check_output(['git','-C',str(root),'rev-parse',commit],text=True).strip()
  body+=p(link('commit/'+sha,'Commit verificável: '+sha))
 if n in ['9','10']:body+=p(link('issues/'+('7' if n=='9' else '8'),'Issue de entrega'))
 if commit:
  record=subprocess.check_output(['git','-C',str(root),'show','-s','--format=Commit: %H%nData: %aI%nAssunto: %s',commit],text=True)
  body+=p('Registro extraído de git show (data original do commit; nas atividades 9 e 10 a ficha usa a abertura da issue):')+'<pre style="font:8pt monospace;white-space:pre-wrap;overflow-wrap:anywhere">'+html.escape(record)+'</pre>'
 if n!='11':body+=img('prints/atividade-'+n+'.png','Captura da página real do GitHub. O registro textual acima preserva hash e horário exatos do commit.')
 else:body+=p(link('issues/5','Backlog de assinatura e cotas (não equivale à entrega)'))+p('Dificuldade e próximo passo: concluir enforcement das cotas, configurar credenciais válidas e registrar um teste de assinatura, cancelamento e repetição de webhook. Não há print de conclusão a apresentar.')
 parts.append(page('5 Atividades realizadas — atividade '+n,body,'s5' if n=='7' else 'a'+n))
parts.append(page('Evidências históricas de resultado',img('../docs/print-stripe-checkout.png','Checkout histórico da atividade 7, preservado no repositório. Não é teste de 12/11/2026.')+img('../docs/print-beneficio-premium.png','Benefício premium no produto original. Evidência histórica, não validação do plano Creator Pro atual.')))
parts.append(page('6 Considerações finais',p('A evolução do catálogo para um negócio de conteúdo mostra o valor do reaproveitamento de serviços de identidade, persistência, logs e armazenamento. Também mostra que a integração precisa ser validada de ponta a ponta: uma tela de plano ou botão de geração não comprova cobrança recorrente, autorização ou cota corretamente aplicadas.')+p('Para que o PostCraft AI seja um produto pronto, ainda é necessário unificar a versão do produto com a evolução da base, confirmar domínio e stack, testar isolamento com papéis distintos, corrigir configuração de segredos, completar assinatura e limites e observar o ciclo real de pagamento e cancelamento. A entrega registrada em issue precisa ser acompanhada por evidências específicas do sistema acessível.')+p('Este relatório preserva as datas encontradas e registra os atrasos e pendências sem substituir evidência por intenção. A atividade 11 deverá receber nova ficha de conclusão apenas quando houver execução e registro verificáveis.'),'s6'))
parts.append(page('Declaração de autoria',p('Relatório individual referente ao projeto de Luis Gustavo Bonfim Ciaramicoli, elaborado a partir do histórico e dos arquivos de seus repositórios. A redação, a organização e a compilação tiveram assistência de IA. As evidências estão vinculadas às fontes indicadas; limitações e pendências foram explicitadas. A revisão e a responsabilidade pela submissão final cabem ao aluno.')+'<h2>Fontes consultadas</h2>'+p('<a href="https://lapps.studio/disciplinas/introducao-computacao-nuvem/atividades/p2-relatorio-bimestral/">Enunciado oficial da P2</a>')+p(link('tree/d084645','Código do produto no recorte analisado'))+p(link('blob/d084645/db/001_dominio.sql','Migração do domínio'))+p(link('blob/d084645/backend/src/controllers/paymentController.js','Controlador de pagamento'))+p(link('blob/d084645/docker-compose.prod.yml','Compose de produção'))+p('<a href="https://github.com/luisciaramicoli/cloud-atividade/commit/e010665">Evolução posterior na base e relatório de testes locais</a>'),'s7'))
(out/'relatorio.html').write_text('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>P2 — PostCraft AI</title><style>@page{size:A4;margin:20mm 18mm 20mm}body{font:11pt Georgia,serif;color:#182233;line-height:1.5}section{break-before:page}section:first-child{break-before:auto}h1{font: bold 22pt Arial;color:#263e64;margin-bottom:22px}h2{font: bold 13pt Arial}p{text-align:justify}a{color:#245b93;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;font:9pt Arial;line-height:1.4}td,th{border:1px solid #c3ccd8;padding:9px;text-align:left}th{background:#edf2f8}figure{margin:20px 0;break-inside:avoid}img{max-width:100%;max-height:95mm;object-fit:contain}figcaption{font:9pt Arial;color:#48566a}.cover{text-align:center;padding-top:35mm}.cover p{text-align:center}li{margin:18px 0}.diagram{border:1px solid #8296b1;background:#edf2f8;padding:18px;font:11pt Arial;line-height:2}</style>'+''.join(parts)+'</html>',encoding='utf8')
